def fastsin(x):
    assert x < 0x8000
    assert x > -0x8001

    m = (x & 0x3fff) >> 6
    if x >= 0 and x < 0x4000:
        return sintab[m]
    elif x >= 0x4000:
        return sintab[255 - m]
    elif x >= -0x4000:
        return -sintab[255 - m]
    else:
        return -sintab[m]

def ulaw(x):
    x_ = x
    sign = x < 0
    x = min(abs(x), 8158) + 33
    exp = x.bit_length() - 6

    return np.uint8(~(((x >> (exp + 1))&0xf) | (exp << 4) | (sign and 0x80)))

def ulaw_expand(x):
    x = ~x
    sign = x & 0x80
    exp = (x >> 4) & 7
    out = ((((x & 0xF) << 1) | 0x21) << exp) - 33
    if sign:
        return -out
    else:
        return out

class CRC(object):
    def __init__(self, size, polynomial):
        self.state = 0
        self.size = size
        self.polynomial = polynomial

    def reset(self, seed):
        self.state = seed
    
    def update_bit(self, bit):
        self.state = (self.state << 1) | bit
        if self.state & (1 << self.size) != 0:
            self.state = self.state ^ (1 << self.size) ^ self.polynomial
        return self.state

    def update(self, data, bits):
        for n in xrange(bits):
            self.update_bit((data >> (bits - n - 1)) & 1)
        return self.state

class BCH(object):
    def __init__(self, M, K, T, P, G):
        self.M = M
        self.N = (1 << self.M) - 1
        self.K = K
        self.T = T
        self.G = G

        self.a_to_i = array('I', [0] * self.N)
        self.index = array('I', [0] * (self.N + 1))

        value = 1
        for i in xrange(0, self.N):
            self.a_to_i[i] = value
            self.index[value] = i

            value = value << 1
            if value & (1 << self.M):
                value = value ^ P

    def encode(self, data):
        r = 0
        feedback = 0
        rlen = self.N - self.K
        test = 1 << self.K
        for i in xrange(0, self.K):
            test = test >> 1
            r = r << 1

            feedback = bool(r >> rlen)
            if feedback:
                r = r ^ (1 << rlen)

            feedback = bool(data & test) ^ feedback
            if feedback:
                r = r ^ self.G ^ (1 << rlen)

        if bool(r >> rlen):
            r = r ^ (1 << rlen)

        return (data << (self.N - self.K)) | r
        
class Modem(object):
    F_1700 = 13926
    F_2100 = 17203

    def __init__(self):
        self.bch = BCH(7, 99, 4, 0x89, 0x1c9c26b9)
        self.crc = CRC(8, 0x97)
        self.remote_t = 0
        self.local_t = 0
        self.remote = False
        self.memoize = PRECOMPUTED

    def precompute(self):
        for bit in (True, False):
            for t_in in map(np.int16, xrange(0,0x10000)):
                t = t_in + (self.F_2100 if bit else self.F_1700)
                t = np.int16(t)
                b = ulaw(fastsin(t) >> 2)
                b = struct.pack('<B', b)
                self.memoize[(t_in, bit)] = (t, b)

    def get_frame(self, data, end=True):
        hdr = len(data)
        if not end:
            hdr = 0xF
            assert len(data) == 9

        # pad to 9 bytes with NULLs
        data = (data + '\x00' * 9)[:9]

        self.crc.reset(0)
        crc = self.crc.update(hdr, 4)
        for x in data:
            crc = self.crc.update(ord(x) ^ 0x55, 8)

        bits = '{:04b}'.format(hdr)[::-1]
        for x in data:
            bits = '{:08b}'.format(ord(x) ^ 0x55)[::-1] + bits
        bits = '{:08b}'.format(crc)[::-1] + bits

        return self.bch.encode(int(bits, 2))

    def get_frames(self, data):
        frames = []

        while len(data):
            count = min(9, len(data))
            frame_data = data[0:count]
            data = data[count:]

            frames.append(self.get_frame(frame_data, len(data) == 0))

        return frames

    def _encode_bit(self, bit):
        if self.remote:
            t = self.remote_t
        else:
            t = self.local_t

        t, b = self.memoize[(t, bit)]

        if self.remote:
            self.remote_t = t
        else:
            self.local_t = t
        return b

    def encode_bit(self, bit):
        s = ''
        for x in xrange(0, 20):
            s += self._encode_bit(bit)
        return s

    def encode_flag(self):
        s = ''
        for x in '10011':
            s += self.encode_bit(x == '1')
        return s

    def encode_frame(self, frame):
        s = self.encode_flag()
        for i in xrange(0, 112):
            bit = bool(frame & (1 << i))
            s += self.encode_bit(bit)
        return s

    def encode(self, data):
        s = ''
        for frame in self.get_frames(data):
            s += self.encode_frame(frame)
        return s

    def pad(self, samples):
        s = ''
        flip = True
        for x in xrange(samples):
            s += self._encode_bit(flip)
            flip = not flip
        return s

def random_string(minlen, maxlen):
    l = random.randint(minlen, maxlen)
    s = ''
    for x in xrange(l):
        s += chr(random.randint(1, 127))
        #s += random.choice(string.letters + string.digits)
    return s

class BBS(Actions):
    # bytes are sent and received at the same rate, which makes this complicated
    def recv(self, s):
        self.state['modem'].remote = True
        s = self.state['modem'].encode(s)
        self.state['pending'] += s

    def send(self, s, encode=True):
        if encode:
            self.state['modem'].remote = False
            s = self.state['modem'].encode(s)
        self.write(s)
        self.state['sent'] += len(s)

        limit = self.state['sent'] + 80 + 79
        limit = limit - (limit % 80)
        while len(self.state['pending']) < limit-1:
            self.state['modem'].remote = True
            self.state['pending'] += self.state['modem']._encode_bit(True)

    def flush_early(self):
        l = min(len(self.state['pending']), self.state['sent'])
        l = int(l / 80) * 80

        if l > 8000:
            self.read(length=l, expect=self.state['pending'][:l])
            self.state['pending'] = self.state['pending'][l:]
            self.state['sent'] -= l

    def flush(self):
        while self.state['sent'] < len(self.state['pending']):
            self.state['modem'].remote = False
            s = self.state['modem'].encode("\x00")
            self.write(s)
            self.state['sent'] += len(s)
            self.flush_early()
        if len(self.state['pending']) > 0:
            self.read(length=len(self.state['pending']), expect=self.state['pending'])

    def start(self):
        self.state['sent'] = 0
        self.state['pending'] = ''
        self.state['threads'] = []
        self.state['id'] = 1000
        self.state['modem'] = Modem()

        # XXX
        self.menu()
        self.post()

    def next_id(self):
        i = self.state['id']
        self.state['id'] = i + 1
        return i

    def menu(self):
        self.flush_early()
        self.recv("(L)ist, (H)elp, (P)ost, (R)ead\n")

    def list(self):
        if self.chance(0.5) and len(self.state['threads']):
            idx = random.randint(0, len(self.state['threads'])-1)
            tid, subj, messages = self.state['threads'][idx]
            self.send("l %d" % tid)
            for idx in xrange(0, len(messages)):
                msgid, topic, body = messages[idx]
                self.recv("%08d - %s\n" % (msgid, topic))
                assert idx < 40
        else:
            self.send("l")
            for idx in xrange(0, len(self.state['threads'])):
                tid, subj, messages = self.state['threads'][idx]
                self.recv("%08d - %s\n" % (tid, subj))
                assert idx < 40

    def read_msg(self):
        if len(self.state['threads']):
            tid, subj, messages = random.choice(self.state['threads'])
            msgid, topic, body = random.choice(messages)
            self.send("r %d" % msgid)
            self.recv("%08d - %s\n" % (msgid, topic))
            self.recv(body)
        else:
            self.send("r")
            self.recv("Missing required argument.\n")
    
    def post(self):
        msgid = self.next_id()
        topic = random_string(2, 10)
        body = random_string(2, 20)

        if self.chance(0.5) and len(self.state['threads']):
            idx = random.randint(0, len(self.state['threads'])-1)
            tid, subj, messages = self.state['threads'][idx]
            self.state['threads'][idx] = (tid, subj, [(msgid, topic, body)] + messages)
            self.send("p %d" % tid)
        else:
            self.send("p")
            self.state['threads'].insert(0, (msgid, topic, [(self.next_id(), topic, body)]))

        self.recv("Subject?\n")
        self.send(topic)

        self.recv("Body?\n")
        self.send(body)

    def quit(self):
        pass

    def finish(self):
        self.flush()
        # server may not send more bytes, so don't try to read them
        self.write(self.state['modem'].encode("q"))

    def help(self):
        self.send("?")
        self.recv(
            "Available commands:\n" +
            "\t(L)ist [thread-id]\n" +
            "\t\tList all threads, or messages in a thread\n" +
            "\t(P)ost [thread-id]\n" +
            "\t\tPost a new thread, or a reply to a thread\n" +
            "\t(R)ead message-id\n" +
            "\t\tGet message contents\n" +
            "\t(H)elp\n" +
            "\t\tThis screen\n")

